import { describe, it, expect } from "vitest";
import { attachFlyControls } from "./fly-controls";

function makeEnv() {
    const handlers: Record<string, Set<(e: any) => void>> = {};
    const canvas: any = {
        tabIndex: -1,
        hasAttribute: () => false,
        addEventListener: (t: string, h: any) => { (handlers[t] ??= new Set()).add(h); },
        removeEventListener: (t: string, h: any) => { handlers[t]?.delete(h); },
        setPointerCapture() {}, releasePointerCapture() {},
    };
    const camera: any = {
        position: { x: 0, y: 0, z: 0, set(x: number, y: number, z: number) { this.x = x; this.y = y; this.z = z; } },
        target: { x: 0, y: 0, z: 1, set(x: number, y: number, z: number) { this.x = x; this.y = y; this.z = z; } },
        _yaw: 0, _pitch: 0, speed: 1, inertia: 0.9, angularSensitivity: 1000,
    };
    const scene: any = { _beforeRender: [] as ((d: number) => void)[] };
    const fire = (t: string, code: string) => handlers[t]?.forEach((h) => h({ code }));
    const frame = () => scene._beforeRender.forEach((f: (d: number) => void) => f(16));
    const count = () => Object.values(handlers).reduce((n, s) => n + s.size, 0);
    return { canvas, camera, scene, fire, frame, count };
}

describe("attachFlyControls", () => {
    it("shift alone does not move vertically", () => {
        const { canvas, camera, scene, fire, frame } = makeEnv();
        attachFlyControls(camera, canvas, scene);
        fire("keydown", "ShiftLeft");
        for (let i = 0; i < 50; i++) frame();
        expect(camera.position.y).toBe(0);
        fire("keydown", "ShiftRight");
        fire("keydown", "KeyD");
        for (let i = 0; i < 50; i++) frame();
        expect(camera.position.y).toBe(0);
    });
    it("space rises, pagedown sinks, shift triples speed", () => {
        const a = makeEnv();
        attachFlyControls(a.camera, a.canvas, a.scene);
        a.fire("keydown", "Space"); a.frame(); a.fire("keyup", "Space");
        for (let i = 0; i < 30; i++) a.frame();
        expect(a.camera.position.y).toBeGreaterThan(0);
        const up = a.camera.position.y;
        a.fire("keydown", "PageDown"); a.frame(); a.fire("keyup", "PageDown");
        for (let i = 0; i < 60; i++) a.frame();
        expect(a.camera.position.y).toBeLessThan(up);

        const slow = makeEnv(); attachFlyControls(slow.camera, slow.canvas, slow.scene);
        slow.fire("keydown", "KeyW"); slow.frame(); slow.fire("keyup", "KeyW");
        for (let i = 0; i < 80; i++) slow.frame();
        const fast = makeEnv(); attachFlyControls(fast.camera, fast.canvas, fast.scene);
        fast.fire("keydown", "ShiftLeft"); fast.fire("keydown", "KeyW"); fast.frame(); fast.fire("keyup", "KeyW");
        for (let i = 0; i < 80; i++) fast.frame();
        const ds = Math.hypot(slow.camera.position.x, slow.camera.position.z);
        const df = Math.hypot(fast.camera.position.x, fast.camera.position.z);
        expect(df / ds).toBeCloseTo(3, 1);
    });
    it("cleanup removes listeners and frame hook", () => {
        const { canvas, camera, scene, count, frame } = makeEnv();
        const stop = attachFlyControls(camera, canvas, scene);
        expect(count()).toBeGreaterThan(0);
        expect(scene._beforeRender.length).toBe(1);
        stop();
        expect(count()).toBe(0);
        expect(scene._beforeRender.length).toBe(0);
        frame();
    });
});
EOF
